namespace Invoicing;

/// <summary>Resolves the VAT due for a net amount given account and jurisdiction.</summary>
public sealed class VatResolver
{
    private static readonly IReadOnlyDictionary<string, decimal> Rates =
        new Dictionary<string, decimal>(StringComparer.OrdinalIgnoreCase)
        {
            ["GB"] = 0.20m,
            ["DE"] = 0.19m,
            ["FR"] = 0.20m,
            ["IE"] = 0.23m
        };

    public decimal Resolve(Account account, decimal net, string countryCode)
    {
        if (net <= 0m) return 0m;

        var rate = GetBaseRate(countryCode);
        rate = ApplyAccountRules(account, net, rate);
        rate = ApplyHighValueCap(net, rate);
        return net * rate;
    }

    private static decimal GetBaseRate(string countryCode) =>
        countryCode != null && Rates.TryGetValue(countryCode, out var rate) ? rate : 0m;

    private static decimal ApplyAccountRules(Account account, decimal net, decimal rate) =>
        account.Kind switch
        {
            AccountKind.Government => 0m,
            AccountKind.Business when net > 10000m => rate * 0.5m,
            _ => rate
        };

    private static decimal ApplyHighValueCap(decimal net, decimal rate) =>
        rate > 0m && net > 100000m ? Math.Min(rate, 0.15m) : rate;
}
